CREATE TABLE extension_generations(id TEXT PRIMARY KEY,version_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('building','active','retired')),created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX extension_one_active_generation ON extension_generations(state) WHERE state='active';
CREATE TABLE extension_dirty(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(account),chat_id TEXT NOT NULL REFERENCES chats(id),generation TEXT NOT NULL REFERENCES extension_generations(id),policy_generation INTEGER NOT NULL,from_time INTEGER NOT NULL,until_time INTEGER NOT NULL,dirty_revision INTEGER NOT NULL,lease_id TEXT NOT NULL DEFAULT '',lease_until INTEGER NOT NULL DEFAULT 0,claim_revision INTEGER NOT NULL DEFAULT 0,claim_from INTEGER NOT NULL DEFAULT 0,claim_until INTEGER NOT NULL DEFAULT 0,cursor_time INTEGER NOT NULL DEFAULT 0,cursor_id TEXT NOT NULL DEFAULT '',claim_cursor_time INTEGER NOT NULL DEFAULT 0,claim_cursor_id TEXT NOT NULL DEFAULT '',UNIQUE(chat_id,generation));
CREATE INDEX extension_dirty_claim ON extension_dirty(account,generation,lease_until,chat_id);
CREATE TABLE extension_dirty_sources(dirty_id TEXT NOT NULL REFERENCES extension_dirty(id) ON DELETE CASCADE,account TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id),local_revision INTEGER NOT NULL,policy_generation INTEGER NOT NULL,expires_at INTEGER NOT NULL,content_hash TEXT NOT NULL,ordinal INTEGER NOT NULL,PRIMARY KEY(dirty_id,message_id));
CREATE TABLE extension_documents(id TEXT PRIMARY KEY,generation TEXT NOT NULL REFERENCES extension_generations(id),kind TEXT NOT NULL CHECK(kind IN ('text_window','ocr','caption','transcript')),text TEXT NOT NULL,normalized_text TEXT NOT NULL,provenance_json TEXT NOT NULL,spans_json TEXT NOT NULL,passage_tokens INTEGER NOT NULL,content_hash TEXT NOT NULL,source_count INTEGER NOT NULL CHECK(source_count BETWEEN 1 AND 2048));
CREATE INDEX extension_documents_generation ON extension_documents(generation,kind);
CREATE TABLE extension_document_sources(document_id TEXT NOT NULL REFERENCES extension_documents(id) ON DELETE CASCADE,account TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id),local_revision INTEGER NOT NULL,policy_generation INTEGER NOT NULL,expires_at INTEGER NOT NULL,content_hash TEXT NOT NULL,ordinal INTEGER NOT NULL,PRIMARY KEY(document_id,message_id));
CREATE INDEX extension_document_source_message ON extension_document_sources(message_id,document_id);
CREATE VIRTUAL TABLE extension_document_fts USING fts5(normalized_text,tokenize='unicode61 remove_diacritics 2');
CREATE TABLE extension_vectors(document_id TEXT PRIMARY KEY REFERENCES extension_documents(id) ON DELETE CASCADE,generation TEXT NOT NULL REFERENCES extension_generations(id),dimensions INTEGER NOT NULL CHECK(dimensions BETWEEN 1 AND 4096),values_blob BLOB NOT NULL,CHECK(length(values_blob)=dimensions*4));
CREATE TABLE extension_jobs(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(account),kind TEXT NOT NULL CHECK(kind IN ('text_embedding','ocr','caption','transcription','derived_embedding')),generation TEXT NOT NULL REFERENCES extension_generations(id),media_id TEXT NOT NULL DEFAULT '',content_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','leased','complete','failed','cancelled')),attempts INTEGER NOT NULL DEFAULT 0,retry_at INTEGER NOT NULL DEFAULT 0,lease_id TEXT NOT NULL DEFAULT '',lease_until INTEGER NOT NULL DEFAULT 0,last_code TEXT NOT NULL DEFAULT '');
CREATE INDEX extension_jobs_claim ON extension_jobs(account,kind,state,retry_at,lease_until);
CREATE INDEX extension_jobs_media ON extension_jobs(media_id,state);
CREATE TABLE extension_job_sources(job_id TEXT NOT NULL REFERENCES extension_jobs(id) ON DELETE CASCADE,account TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id),local_revision INTEGER NOT NULL,policy_generation INTEGER NOT NULL,expires_at INTEGER NOT NULL,content_hash TEXT NOT NULL,ordinal INTEGER NOT NULL,PRIMARY KEY(job_id,message_id));
CREATE INDEX extension_job_source_message ON extension_job_sources(message_id,job_id);
CREATE TABLE extension_job_documents(job_id TEXT NOT NULL REFERENCES extension_jobs(id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES extension_documents(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,PRIMARY KEY(job_id,document_id));
